const listCameraStatusBySchool = `-- name: ListCameraStatusBySchool :many
SELECT
    cam.id AS camera_id,
    cam.name AS camera_name,
    cr.name AS classroom_name,
    cam.status,
    COALESCE(css.desired_state, 'STOPPED')::text AS desired_state,
    cam.default_quality,
    cam.last_segment_at,
    (
        SELECT COUNT(*)::bigint
        FROM alerts a
        WHERE a.camera_id = cam.id
          AND a.status IN ('OPEN', 'ACKNOWLEDGED')
    ) AS open_alerts,
    (
        SELECT che.event_type
        FROM camera_health_events che
        WHERE che.camera_id = cam.id
        ORDER BY che.created_at DESC
        LIMIT 1
    ) AS last_health_event
FROM cameras cam
LEFT JOIN classrooms cr ON cr.id = cam.classroom_id
LEFT JOIN camera_stream_states css ON css.camera_id = cam.id
WHERE cam.school_id = $1
ORDER BY cam.name
`

type ListCameraStatusBySchoolRow struct {
	CameraID        uuid.UUID          `json:"camera_id"`
	CameraName      string             `json:"camera_name"`
	ClassroomName   pgtype.Text        `json:"classroom_name"`
	Status          string             `json:"status"`
	DesiredState    string             `json:"desired_state"`
	DefaultQuality  string             `json:"default_quality"`
	LastSegmentAt   pgtype.Timestamptz `json:"last_segment_at"`
	OpenAlerts      int64              `json:"open_alerts"`
	LastHealthEvent string             `json:"last_health_event"`
}

func (q *Queries) ListCameraStatusBySchool(ctx context.Context, schoolID uuid.UUID) ([]ListCameraStatusBySchoolRow, error) {
	rows, err := q.db.Query(ctx, listCameraStatusBySchool, schoolID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListCameraStatusBySchoolRow{}
	for rows.Next() {
		var i ListCameraStatusBySchoolRow
		if err := rows.Scan(
			&i.CameraID,
			&i.CameraName,
			&i.ClassroomName,
			&i.Status,
			&i.DesiredState,
			&i.DefaultQuality,
			&i.LastSegmentAt,
			&i.OpenAlerts,
			&i.LastHealthEvent,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

