const sumApprovedPaymentsCentsScoped = `-- name: SumApprovedPaymentsCentsScoped :one
SELECT COALESCE(SUM(p.amount_cents), 0)::bigint AS total_cents
FROM payments p
WHERE p.status = 'APPROVED'
  AND p.approved_at >= $1
  AND p.approved_at < $2
  AND ($3::uuid[] IS NULL OR p.school_id = ANY($3::uuid[]))
`

type SumApprovedPaymentsCentsScopedParams struct {
	ApprovedAt   pgtype.Timestamptz `json:"approved_at"`
	ApprovedAt_2 pgtype.Timestamptz `json:"approved_at_2"`
	SchoolIds    []uuid.UUID        `json:"school_ids"`
}

func (q *Queries) SumApprovedPaymentsCentsScoped(ctx context.Context, arg SumApprovedPaymentsCentsScopedParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumApprovedPaymentsCentsScoped, arg.ApprovedAt, arg.ApprovedAt_2, arg.SchoolIds)
	var total_cents int64
	err := row.Scan(&total_cents)
	return total_cents, err
}

const sumLatestStorageBytesScoped = `-- name: SumLatestStorageBytesScoped :one
SELECT COALESCE(SUM(latest.total_bytes), 0)::bigint AS total_bytes
FROM (
    SELECT DISTINCT ON (su.school_id)
        su.total_bytes
    FROM storage_usage su
    WHERE ($1::uuid[] IS NULL OR su.school_id = ANY($1::uuid[]))
    ORDER BY su.school_id, su.date DESC
) latest
`

func (q *Queries) SumLatestStorageBytesScoped(ctx context.Context, schoolIds []uuid.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, sumLatestStorageBytesScoped, schoolIds)
	var total_bytes int64
	err := row.Scan(&total_bytes)
	return total_bytes, err
}

